"""Attach reviewed product-value reports to their exact component releases.

[Role] Publish the per-component views generated by value-verify.
[Invariants] Formal tags and measured sources must match. Existing identical
attachments are reused; conflicting attachments are never overwritten.
Product publication requires every expected attachment to already exist.
[Timeouts & Locks] Every GitHub operation has a 60-second budget; no retries.
[Side-Effect Policy] Adds versioned public attachments only with --publish.
"""

from __future__ import annotations

import argparse
import json
import subprocess
from pathlib import Path

from collect_product_benchmarks import github, tag_revision

from mindie_bench.io import read_json
from mindie_bench.value_publish import component_name, write_component_views
from mindie_bench.value_release import verify_publication


def attach(
    *, suite, evidence, manifest, output, publish=False, require_existing=False, fetch=github
):
    report = verify_publication(suite=suite, evidence=evidence, manifest=manifest)
    if not report["release_gate"]:
        raise ValueError("product value evidence is incomplete")
    targets = read_json(manifest)
    write_component_views(report, targets, output)
    operations = []
    for target in targets["repositories"]:
        repository, version = target["repository"], target["version"]
        path = f"repos/{repository}/releases/tags/v{version}"
        release = fetch(path)
        if release["draft"] or release["prerelease"]:
            raise ValueError(f"component release is not formal: {repository}")
        if tag_revision(repository, version, fetch) != target["revision"]:
            raise ValueError(f"component tag differs from measured source: {repository}")
        assets = {asset["name"]: asset for asset in release["assets"]}
        directory = output / component_name(repository)
        for file in sorted(directory.glob(f"product-{report['product_version']}-value-results.*")):
            existing = assets.get(file.name)
            if existing:
                data = fetch(f"repos/{repository}/releases/assets/{existing['id']}", binary=True)
                if data != file.read_bytes():
                    raise ValueError(f"existing value attachment differs: {repository}/{file.name}")
                state = "already_present"
            elif require_existing:
                raise ValueError(f"missing value attachment: {repository}/{file.name}")
            else:
                state = "ready"
            operations.append({
                "repository": repository, "tag": f"v{version}", "asset": file.name,
                "path": file, "status": state,
            })
    # Finish all read-only checks before the first external write.
    for operation in operations:
        if publish and operation["status"] == "ready":
            subprocess.run([
                "gh", "release", "upload", operation["tag"], str(operation["path"]),
                "--repo", operation["repository"],
            ], check=True, capture_output=True, timeout=60)
            operation["status"] = "uploaded"
        operation.pop("path")
    return operations


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    for name in ("suite", "evidence", "manifest", "output"):
        parser.add_argument("--" + name, type=Path, required=True)
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument("--publish", action="store_true")
    mode.add_argument("--require-existing", action="store_true")
    print(json.dumps(attach(**vars(parser.parse_args())), indent=2))


if __name__ == "__main__":
    main()
